'use client'

import * as React from 'react'
import { Dialog as DialogPrimitive } from 'radix-ui'
import { cn } from '@/lib/utils'
import { Button } from '@/registry/satin/ui/button'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * Dialog, 1:1 with the uiKit `Dialog` set (465:66873): variant default or destructive.
 * A 425px popover surface (min 360, max 560, never wider or taller than the screen less 16px a side; the body scrolls), radius-2xl, border/default, the shadcn `lg`
 * shadow. Header 16 / 16 / 8 with a 14px medium title and a 13px muted description, a body
 * 16px in with a 12px gap (body text, any content, an optional `DialogAlert`), then a
 * right-aligned footer with 16px padding on both variants, on the same inset as the header and
 * body. The close button is a 36px tertiary icon button 8px from the top-right corner.
 *
 * Built on the Radix Dialog. The destructive variant keeps the same primitive but takes
 * `role="alertdialog"`, so screen readers announce it as an alert. Pass `container` to portal
 * it into a positioned element (the docs stage) instead of the page; the dialog then centres
 * inside that element rather than the viewport.
 *
 * Other props, `ref` included, go to the dialog's content panel.
 */
export type DialogVariant = 'default' | 'destructive'

export interface DialogProps
  extends Omit<React.ComponentProps<typeof DialogPrimitive.Content>, 'title' | 'children' | 'asChild' | 'onOpenAutoFocus'> {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Optional element that opens the dialog (rendered with `asChild`, so pass a Button). */
  trigger?: React.ReactNode
  title: React.ReactNode
  description?: React.ReactNode
  variant?: DialogVariant
  /** A `DialogAlert` shown under the body, for a side effect the user must know about. */
  alert?: React.ReactNode
  /** The actions on the right of the footer. Leave it out for a read-only dialog. */
  footer?: React.ReactNode
  /** Figma's `footerSlot`: content on the left of the footer, e.g. a "Don't ask again" checkbox. */
  footerStart?: React.ReactNode
  /** Body. A string renders as body text (13px, text/default). */
  children?: React.ReactNode
  /** Show the close button in the corner. */
  closeButton?: boolean
  /** Modal blocks the page and shows the overlay; turn it off for inline previews. */
  modal?: boolean
  /** Portal target. Defaults to `document.body`. */
  container?: HTMLElement | null
  /** Called when focus moves into the dialog on open; `preventDefault()` keeps it where it was. */
  onOpenAutoFocus?: (event: Event) => void
  className?: string
}

/** The X from Figma's close button (`icon` 16px, 1.25 stroke). */
/** @internal Shared by Satin's own components; not part of the public API and may change in any release. */
export function CloseIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
      <path
        d="M4.50551 11.4951L8.0006 8M8.0006 8L11.4957 4.50491M8.0006 8L4.50551 4.50491M8.0006 8L11.4957 11.4951"
        stroke="currentColor"
        strokeWidth="1.25"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

export function Dialog({
  open,
  defaultOpen,
  onOpenChange,
  trigger,
  title,
  description,
  variant = 'default',
  alert,
  footer,
  footerStart,
  children,
  closeButton = true,
  modal = true,
  container,
  onOpenAutoFocus,
  className,
  ...props
}: DialogProps) {
  const labels = useSatinLabels()
  // Inside a container the dialog is laid out against it, not the viewport.
  const position = container ? 'absolute' : 'fixed'
  const hasBody = children != null || alert != null

  return (
    <DialogPrimitive.Root open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange} modal={modal}>
      {trigger && <DialogPrimitive.Trigger asChild>{trigger}</DialogPrimitive.Trigger>}
      <DialogPrimitive.Portal container={container}>
        {/* No overlay in Figma; black-a40 is the kit's scrim colour. Only drawn when modal. */}
        <DialogPrimitive.Overlay
          className={cn(
            position,
            'sa:inset-0 sa:z-50 sa:bg-black-a40',
          )}
        />
        <div className={cn(position, 'sa:pointer-events-none sa:inset-0 sa:z-50 sa:grid sa:grid-cols-[minmax(0,1fr)] sa:grid-rows-[minmax(0,1fr)] sa:place-items-center sa:p-4')}>
          <DialogPrimitive.Content
            // No description: tell Radix on purpose, so it doesn't warn (an aria-describedby passed in still wins).
            {...(description ? {} : { 'aria-describedby': undefined })}
            {...props}
            role={variant === 'destructive' ? 'alertdialog' : 'dialog'}
            data-slot="dialog"
            data-variant={variant}
            onOpenAutoFocus={onOpenAutoFocus}
            className={cn(
              'sa:pointer-events-auto sa:relative sa:flex sa:max-h-full sa:w-[425px] sa:max-w-[min(560px,100%)] sa:min-w-[min(360px,100%)] sa:flex-col sa:overflow-clip',
              'sa:rounded-2xl sa:border sa:border-border-default sa:bg-bg-popover',
              'sa:[box-shadow:0_4px_6px_-4px_var(--effect-shadow-sm),0_10px_15px_-3px_var(--effect-shadow-sm)]',
              'sa:focus-visible:outline-none',
              'sa:data-[state=open]:animate-[satin-enter_var(--sa-duration-base)_var(--sa-ease-out)]',
              className,
            )}
          >
            <div className="sa:flex sa:min-h-0 sa:flex-col sa:gap-3">
              <div className="sa:flex sa:shrink-0 sa:flex-col sa:gap-0.5 sa:px-4 sa:pt-4 sa:pb-2">
                <DialogPrimitive.Title className="sa:pr-8 sa:text-base sa:leading-[14px] sa:font-medium sa:tracking-normal sa:text-text-default">
                  {title}
                </DialogPrimitive.Title>
                {description ? (
                  <DialogPrimitive.Description className="sa:text-body sa:text-text-muted">{description}</DialogPrimitive.Description>
                ) : null}
              </div>
              {hasBody && (
                <div className="sa:flex sa:min-h-0 sa:flex-col sa:gap-3 sa:overflow-y-auto sa:px-4 sa:pb-3">
                  {typeof children === 'string' ? <p className="sa:text-body sa:text-text-default">{children}</p> : children}
                  {alert}
                </div>
              )}
            </div>

            {(footer || footerStart) && (
              <div className="sa:flex sa:shrink-0 sa:flex-wrap sa:items-center sa:justify-end sa:gap-3 sa:p-4">
                {footerStart && <div className="sa:flex sa:min-w-0 sa:flex-1 sa:items-center">{footerStart}</div>}
                <div className="sa:flex sa:shrink-0 sa:items-center sa:gap-2">{footer}</div>
              </div>
            )}

            {closeButton && (
              <DialogPrimitive.Close asChild>
                <Button
                  variant="tertiary"
                  size="xl"
                  iconOnly
                  aria-label={labels.close}
                  className="sa:absolute sa:top-[7px] sa:right-[7px] sa:rounded-lg"
                >
                  <CloseIcon />
                </Button>
              </DialogPrimitive.Close>
            )}
          </DialogPrimitive.Content>
        </div>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

/** Wrap a footer button in this to make it close the dialog: `<DialogClose asChild><Button…/></DialogClose>`. */
export const DialogClose = DialogPrimitive.Close

/* ------------------------------------------------------------------------------------------ */

export type DialogAlertIntent = 'info' | 'success' | 'warning' | 'error'

/**
 * Alert, 1:1 with the uiKit `Alert` set (475:27871): the inline notice inside a dialog.
 * radius-xl, 16 / 12 padding, the intent's status bg, a 16px status icon in the intent's
 * status fg, a 14px medium title over a 13px muted description, and an optional 28px close.
 */
export interface DialogAlertProps extends Omit<React.ComponentProps<'div'>, 'title'> {
  intent?: DialogAlertIntent
  title: React.ReactNode
  description?: React.ReactNode
  /** Hide the status icon. */
  icon?: boolean
  /** Shows the close button; called when it is pressed. */
  onDismiss?: () => void
}

const alertTint: Record<DialogAlertIntent, string> = {
  info: 'sa:bg-status-sky-bg sa:text-status-sky-fg',
  success: 'sa:bg-status-green-bg sa:text-status-green-fg',
  warning: 'sa:bg-status-amber-bg sa:text-status-amber-fg',
  error: 'sa:bg-status-red-bg sa:text-status-red-fg',
}

/** The four status glyphs from Figma (16px, 1.25 stroke), drawn in currentColor. */
export function StatusIcon({ intent }: { intent: DialogAlertIntent }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden className="sa:shrink-0">
      <g stroke="currentColor" style={{ strokeWidth: 1.25 }} strokeLinecap="round" strokeLinejoin="round">
        {intent === 'success' ? (
          <path d="M3.33333 8.66667L6 11.3333L12.6667 4.66667" />
        ) : (
          <>
            {intent === 'info' ? (
              <>
                <path d="M8 7.70494V10.6557" />
                <path d="M8 5.35022L8.0059 5.34366" />
              </>
            ) : (
              <>
                <path d="M8 5.34428V8.29506" />
                <path d="M8 10.6563L8.0059 10.6498" />
              </>
            )}
            <path d="M8 13.9015C11.2593 13.9015 13.9015 11.2593 13.9015 8C13.9015 4.74066 11.2593 2.09845 8 2.09845C4.74066 2.09845 2.09845 4.74066 2.09845 8C2.09845 11.2593 4.74066 13.9015 8 13.9015Z" />
          </>
        )}
      </g>
    </svg>
  )
}

export function DialogAlert({
  intent = 'info',
  title,
  description,
  icon = true,
  onDismiss,
  className,
  ...props
}: DialogAlertProps) {
  const labels = useSatinLabels()
  return (
    <div
      role={intent === 'error' || intent === 'warning' ? 'alert' : 'status'}
      data-slot="dialog-alert"
      data-intent={intent}
      className={cn('sa:flex sa:w-full sa:items-center sa:gap-3 sa:rounded-xl sa:px-4 sa:py-3', alertTint[intent], className)}
      {...props}
    >
      <div className="sa:flex sa:min-w-0 sa:flex-1 sa:items-center sa:gap-2.5">
        {icon && <StatusIcon intent={intent} />}
        <div className="sa:flex sa:min-w-0 sa:flex-1 sa:flex-col">
          <p className="sa:text-base sa:font-medium sa:text-text-default">{title}</p>
          {description ? <p className="sa:text-body sa:text-text-muted">{description}</p> : null}
        </div>
      </div>
      {onDismiss && (
        <Button variant="tertiary" iconOnly aria-label={labels.dismiss} onClick={onDismiss}>
          <CloseIcon />
        </Button>
      )}
    </div>
  )
}
